document.addEventListener('click',e=>{const id=e.target.dataset.stockReplace||e.target.dataset.stockOut;if(!id||!isStockManager())return;const item=outOfStock.find(entry=>entry.id===id);if(!item)return;if(e.target.dataset.stockOut){item.replaced=false;item.replacedDate='';item.date=today();toast('Item marked out of stock again');}else{item.replaced=true;item.replacedDate=today();toast('Item marked as replaced');}save();syncStock('updateStock',item);});
$$('[data-payment-mode]').forEach(button=>button.addEventListener('click',()=>{const r=records.find(item=>item.id===$('#payment-record-id').value);if(r)setPaymentMode(button.dataset.paymentMode,r);}));$('#payment-form').addEventListener('submit',e=>{e.preventDefault();const id=$('#payment-record-id').value,r=records.find(x=>x.id===id),amount=Number($('#payment-amount').value),mode=$('#payment-mode').value,time=new Date().toTimeString().slice(0,5),enteredBy=currentUser?.username||currentUser?.label||'Not recorded';if(!r||!Number.isFinite(amount)||amount<=0)return;const history=noteEntries(r);if(mode==='debt'){const text=`${r.type==='receivable'?'Lending / credit added':'Debt increased'}: ${money.format(amount)}`;r.amount=Number(r.amount)+amount;r.notes=[r.notes,text].filter(Boolean).join(' · ');r.noteEntries=[...history,{text,date:today(),time,enteredBy}];r.status=statusOf(r);save();sync('update',{record:r});$('#payment-dialog').close();toast('Amount added to debt');return;}const actual=Math.min(Math.abs(Number(r.amount)),paid(r)+amount)-paid(r);if(actual<=0)return;const text=`${r.type==='receivable'?'Payment received':'Payment made'}: ${money.format(actual)}`;r.payments=paymentEntries(r);r.payments.push({amount:actual,date:today(),time});r.paidAmount=paid(r)+actual;r.notes=[r.notes,text].filter(Boolean).join(' · ');r.noteEntries=[...history,{text,date:today(),time,enteredBy}];r.status=statusOf(r);save();sync('update',{record:r});$('#payment-dialog').close();toast('Payment recorded as cash movement');});
